#include "../core/controller.h"
#include <cstdio>
#include <cassert>
CoreInput good(){CoreInput a{};a.command_mode=1;a.front_distance_m=2.0;a.front_valid=1;a.person_distance_m=3.0;a.side_distance_m=0.6;a.pose_sigma_m=0.15;a.mqtt_age_s=0.1;a.imu_age_s=0.1;a.encoder_age_s=0.1;a.tof_age_s=0.1;return a;}
int main(){CoreOutput out{};auto a=good(); core_step(&a,&out);assert(out.status==1&&out.left_mps>0);a.estop=1;core_step(&a,&out);assert(out.status==9&&out.left_mps==0);a=good();a.mqtt_age_s=2;core_step(&a,&out);assert(out.status==5);a=good();a.front_valid=0;core_step(&a,&out);assert(out.status==4);a=good();a.pose_sigma_m=1;core_step(&a,&out);assert(out.status==6);a=good();a.person_confidence=.9;a.person_distance_m=.4;core_step(&a,&out);assert(out.status==2);a=good();a.front_distance_m=.2;core_step(&a,&out);assert(out.status==3);a=good();a.command_mode=0;core_step(&a,&out);assert(out.status==0&&out.left_mps==0&&out.right_mps==0);a=good();a.command_mode=2;core_step(&a,&out);assert(out.status==7&&out.left_mps<0&&out.right_mps>0);a=good();a.near_turn=-1;core_step(&a,&out);assert(out.turn_signal==-1);a=good();a.command_mode=3;a.marker_confirmed=1;core_reset();core_step(&a,&out);assert(out.status==8&&out.chime_event==1);core_step(&a,&out);assert(out.chime_event==0);a=good();a.command_mode=3;a.marker_confirmed=0;core_step(&a,&out);assert(out.status==6);printf("12 shared-controller safety checks passed\n");}
